#hud .wchip .wname { flex: 1; font-size: 11px; letter-spacing: 1px; }
#hud .wchip .wammo { font-size: 11px; min-width: 3ch; text-align: right; }
#hud .wchip .wbar { display: none; height: 3px; margin-top: 5px; background: rgba(244, 247, 255, 0.18); }
body.natural #hud .wchip .wbar { background: rgba(125, 249, 255, 0.18); }
#hud .wchip .wbarfill { height: 100%; width: 0; background: var(--acc); }
#hud .therm { margin-top: 9px; font-size: 11px; letter-spacing: 2px; }
