  hud.appendChild(help);

  document.body.appendChild(hud);

  // ---- HUD updaters ----
  const AR_pad4 = v => String(Math.max(0, Math.min(9999, Math.round(v)))).padStart(4, '0');
  const AR_pad1 = v => String(Math.max(0, Math.min(9999.9, v))).padStart(6, '0');

  function AR_updateAmmo() {
    for (let i = 0; i < AR_WEAPONS.length; i++) {
