  // ---- weapons ----
  function AR_writeProj(i) {
    const p = AR_pData[i];
    AR_tV.copy(p.vel).normalize();
    AR_tQ.setFromUnitVectors(AR_Z_AXIS, AR_tV);
    AR_tS.set(p.w.rad, p.w.rad, p.w.len); // long axis on Z: quaternion maps +Z to velocity
    AR_tM.compose(p.pos, AR_tQ, AR_tS);
    AR_pMesh.setMatrixAt(i, AR_tM);
  }

  function AR_touchProj(i) {
    AR_pMesh.setColorAt(i, state.thermal ? AR_WHOT_T : AR_pData[i].w.tcolor);
    AR_pMesh.count = AR_pCount;
    AR_pMesh.instanceMatrix.needsUpdate = true;
    if (AR_pMesh.instanceColor) AR_pMesh.instanceColor.needsUpdate = true;
  }

  // ballistic launch solver: choose the initial velocity so the projectile, integrated
  // with the SAME semi-implicit Euler / fixed step as tick(), arrives at `target`.
  // The integrator is linear in v0 per axis, so this is EXACT:
  //   A = displacement per unit initial velocity (identical for all axes)
  //   B = y-displacement from gravity alone (dragged)
  //   v0 = (D - B) / A
  function AR_solveLaunch(from, to, w) {
    const dx = to.x - from.x, dy = to.y - from.y, dz = to.z - from.z;
    const dist = Math.sqrt(dx * dx + dy * dy + dz * dz);
    const T = clamp(dist / w.speed, 0.3, 12);
    const n = Math.max(1, Math.round(T / AR_H));
    const f = w.drag ? 1 - w.drag * AR_H : 1;
    let A = 0, pow = 1;
    for (let s = 0; s < n; s++) { pow *= f; A += pow * AR_H; }
    let B = 0, vyy = 0;
    for (let s = 0; s < n; s++) { vyy = (vyy - (w.g || 0) * AR_H) * f; B += vyy * AR_H; }
    return new THREE.Vector3(dx / A, (dy - B) / A, dz / A);
  }

  function AR_spawnProj(from, target) {
    if (AR_pCount >= 200) return;
    const w = AR_WEAPONS[AR_sel];
    const i = AR_pCount++;
    const vel = AR_solveLaunch(from, target, w);
    AR_pData[i] = { pos: from.clone(), vel: vel, w: w,
      target: w.name === 'NUKE' ? target.clone() : null, age: 0 };
    AR_writeProj(i);
    AR_touchProj(i);
  }

  function AR_killProj(i) {
    const last = AR_pCount - 1;
    if (i !== last) {
      AR_pData[i] = AR_pData[last];
      AR_writeProj(i);
      AR_touchProj(i);
    }
    AR_pCount = last;
    AR_pMesh.count = AR_pCount;
    if (AR_pMesh.instanceColor) AR_pMesh.instanceColor.needsUpdate = true;
  }

  // ---- procedural weapon audio (WebAudio; starts after first user gesture) ----
  let AR_audio = null;
  let AR_master = null;
  let AR_audioSeed = 0xAC130;

  function AR_randAudio() {
    AR_audioSeed = (Math.imul(1664525, AR_audioSeed) + 1013904223) >>> 0;
    return AR_audioSeed / 4294967296;
  }

  function AR_audioInit() {
    if (!AR_audio) {
      const AC = window.AudioContext || window.webkitAudioContext;
      if (!AC) return null;
      AR_audio = new AC();
      const comp = AR_audio.createDynamicsCompressor();
      comp.threshold.value = -10; comp.knee.value = 12; comp.ratio.value = 8;
      comp.attack.value = 0.002; comp.release.value = 0.22;
      AR_master = AR_audio.createGain();
      AR_master.gain.value = 0.72;
      AR_master.connect(comp).connect(AR_audio.destination);
    }
    if (AR_audio.state === 'suspended') AR_audio.resume();
    return AR_audio;
  }

  function AR_tone(f0, f1, dur, vol, type = 'sine', delay = 0) {
    const ac = AR_audioInit(); if (!ac) return;
    const now = ac.currentTime + delay;
    const o = ac.createOscillator(), g = ac.createGain();
    o.type = type;
    o.frequency.setValueAtTime(Math.max(1, f0), now);
    o.frequency.exponentialRampToValueAtTime(Math.max(1, f1), now + dur);
    g.gain.setValueAtTime(0.0001, now);
    g.gain.exponentialRampToValueAtTime(vol, now + 0.006);
    g.gain.exponentialRampToValueAtTime(0.0001, now + dur);
    o.connect(g).connect(AR_master); o.start(now); o.stop(now + dur + 0.02);
  }

  function AR_noise(dur, vol, cutoff, delay = 0, highpass = 0) {
    const ac = AR_audioInit(); if (!ac) return;
    const now = ac.currentTime + delay;
    const n = Math.max(64, Math.ceil(ac.sampleRate * dur));
    const buf = ac.createBuffer(1, n, ac.sampleRate), d = buf.getChannelData(0);
    for (let i = 0; i < n; i++) d[i] = (AR_randAudio() * 2 - 1) * (1 - i / n * 0.35);
    const src = ac.createBufferSource(), lp = ac.createBiquadFilter();
    const hp = ac.createBiquadFilter(), g = ac.createGain();
    src.buffer = buf; lp.type = 'lowpass'; lp.frequency.value = cutoff;
    hp.type = 'highpass'; hp.frequency.value = highpass;
    g.gain.setValueAtTime(0.0001, now);
    g.gain.exponentialRampToValueAtTime(vol, now + 0.004);
    g.gain.exponentialRampToValueAtTime(0.0001, now + dur);
    src.connect(lp).connect(hp).connect(g).connect(AR_master);
    src.start(now); src.stop(now + dur + 0.02);
  }

  function AR_audioShot(w) {
    const n = w.name;
    if (n.indexOf('25MM') >= 0) {
      AR_noise(0.055, 0.18, 7500, 0, 900); AR_tone(135, 62, 0.095, 0.24, 'square');
      AR_tone(920, 410, 0.035, 0.045, 'sawtooth', 0.012);
    } else if (n.indexOf('40MM') >= 0) {
      AR_noise(0.22, 0.34, 2600, 0, 70); AR_tone(92, 34, 0.34, 0.52, 'sine');
      AR_tone(210, 72, 0.12, 0.18, 'triangle', 0.015);
    } else if (n.indexOf('70MM') >= 0) {
      AR_noise(0.55, 0.25, 4200, 0, 180); AR_tone(78, 42, 0.65, 0.35, 'sawtooth');
      AR_tone(420, 125, 0.32, 0.08, 'triangle', 0.04);
    } else if (n.indexOf('NUKE') >= 0) {
      AR_noise(0.9, 0.30, 1800, 0, 40); AR_tone(54, 24, 1.1, 0.62, 'sawtooth');
      AR_tone(180, 48, 0.55, 0.18, 'triangle', 0.06);
    }
  }

  function AR_audioImpact(w) {
    const n = w.name;
    if (n.indexOf('25MM') >= 0) {
