    } else if (n.indexOf('70MM') >= 0) {
      AR_noise(0.85, 0.45, 2200, 0, 25); AR_tone(68, 19, 1.05, 0.65, 'sine');
      AR_tone(135, 34, 0.42, 0.22, 'sawtooth', 0.025);
    } else if (n.indexOf('NUKE') >= 0) {
      AR_noise(2.8, 0.72, 1700, 0, 12); AR_noise(0.09, 0.52, 11000, 0, 700);
      AR_tone(48, 14, 3.2, 0.90, 'sine'); AR_tone(82, 19, 1.5, 0.52, 'sawtooth', 0.08);
      AR_tone(61, 16, 1.8, 0.42, 'sine', 0.28); AR_noise(1.35, 0.32, 850, 0.42, 8);
      AR_tone(39, 12, 2.4, 0.55, 'triangle', 0.58);
    }
  }

  function AR_explode(p, w) {
    AR_audioImpact(w);
    if (state.destruction) state.destruction.hit(p, w.blast, w.dmg, w.power, w.name);
  }

  function fireAt(point) {
    if (!point || typeof point.x !== 'number') return;
    if (AR_reloading[AR_sel] || AR_ammo[AR_sel] <= 0) return;
    AR_ammo[AR_sel]--;
    AR_audioShot(AR_WEAPONS[AR_sel]);
    AR_muz.set(-4.5, -2.2, 1.8).applyQuaternion(AR_gs.group.quaternion).add(AR_gs.pos);
    AR_spawnProj(AR_muz, point);
    if (AR_ammo[AR_sel] <= 0) {
      AR_reloading[AR_sel] = true;
      AR_reloadT[AR_sel] = 0;
    }
    AR_updateAmmo();
  }

  function AR_tryHold() {
    if (!AR_aimValid) return;
    if (AR_reloading[AR_sel] || AR_ammo[AR_sel] <= 0 || AR_cd[AR_sel] > 0) return;
    AR_cd[AR_sel] = 1 / AR_WEAPONS[AR_sel].fireRate;
    fireAt(AR_aimPoint);
  }

  function selectWeapon(i) {
    i = clamp(Math.round(i), 0, AR_WEAPONS.length - 1);
    if (i === AR_sel) return;
    AR_sel = i;
    for (let j = 0; j < AR_WEAPONS.length; j++) AR_chips[j].classList.toggle('sel', j === i);
    AR_updateAmmo();
  }

  // sensor zoom: discrete steps, like the real FLIR (FOV 30/18/10)
  function zoom(delta) {
    AR_zoom = clamp(AR_zoom + delta, 0, 2);
    state.camera.fov = AR_FOVS[AR_zoom];
    state.camera.updateProjectionMatrix();
    AR_updateZoom();
  }

  // sensor slew: point the reticle at NDC (nx, ny) and latch it
  function slew(nx, ny) {
    AR_ndc.x = clamp(nx, -1.2, 1.2);
    AR_ndc.y = clamp(ny, -1.2, 1.2);
    AR_aimActive = true;
  }

  function setThermal(on) {
    state.thermal = on;
    if (state.applyThermal) state.applyThermal(on);
    document.body.classList.toggle('thermal', on);
    document.body.classList.toggle('natural', !on);
    AR_ringMat.color.setHex(on ? 0xdfe6ff : 0xff3344);
    AR_laserMat.color.setHex(on ? 0x9aa0b0 : 0xff2233);
    AR_updateTherm();
  }

  function AR_toggleHelp() {
    AR_helpOn = !AR_helpOn;
    help.classList.toggle('on', AR_helpOn);
  }

  function reset() {
    for (let i = 0; i < AR_WEAPONS.length; i++) {
      AR_ammo[i] = AR_WEAPONS[i].maxAmmo;
      AR_reloading[i] = false;
      AR_reloadT[i] = 0;
      AR_cd[i] = 0;
    }
    AR_sel = 0;
    for (let j = 0; j < AR_WEAPONS.length; j++) AR_chips[j].classList.toggle('sel', j === 0);
    AR_pCount = 0;
    AR_pAcc = 0;
    AR_pMesh.count = 0;
    AR_rmb = false;
    AR_space = false;
    refreshHud();
  }

  // ---- input ----
  let AR_lmb = null;
  let AR_lmbHeld = false;

  const AR_onDown = e => {
    if (e.button === 0) {
      AR_lmb = { x0: e.clientX, y0: e.clientY, dragged: false };
      AR_lmbHeld = true;
      AR_tryHold();
    } else if (e.button === 2) {
      AR_rmb = true;
      AR_tryHold();
    }
  };

  const AR_onMove = e => {
    AR_ptrInside = true;
    AR_ndc.x = (e.clientX / window.innerWidth) * 2 - 1;
    AR_ndc.y = -(e.clientY / window.innerHeight) * 2 + 1;
    AR_aimActive = true;
    if (AR_lmb && !AR_lmb.dragged && Math.hypot(e.clientX - AR_lmb.x0, e.clientY - AR_lmb.y0) > 5) {
      AR_lmb.dragged = true; // a swipe is not a shot
    }
  };

  const AR_onUp = e => {
    if (e.button === 2) AR_rmb = false;
    if (e.button === 0) { AR_lmbHeld = false; AR_lmb = null; }
  };

  window.addEventListener('pointerdown', AR_onDown);
  window.addEventListener('pointermove', AR_onMove);
  window.addEventListener('pointerup', AR_onUp);
  window.addEventListener('pointercancel', AR_onUp);
  window.addEventListener('blur', () => {
    AR_rmb = false;
    AR_space = false;
    AR_lmbHeld = false;
    AR_lmb = null;
    AR_ptrInside = false;
  });
  window.addEventListener('contextmenu', e => e.preventDefault());
  window.addEventListener('wheel', e => {
    e.preventDefault();
    zoom(e.deltaY < 0 ? 1 : -1);
  }, { passive: false });
  document.addEventListener('pointerover', () => { AR_ptrInside = true; });
  document.addEventListener('pointerout', e => { if (!e.relatedTarget) AR_ptrInside = false; });

  window.addEventListener('keydown', e => {
    if (e.code === 'Space') {
      e.preventDefault();
      AR_space = true;
      AR_tryHold();
    } else if (e.code === 'Digit1') selectWeapon(0);
    else if (e.code === 'Digit2') selectWeapon(1);
    else if (e.code === 'Digit3') selectWeapon(2);
    else if (e.code === 'Digit4') selectWeapon(3);
    else if (e.key === 'n' || e.key === 'N') setThermal(!state.thermal);
    else if (e.key === 'r' || e.key === 'R') { if (state.onResetRequest) state.onResetRequest(); }
    else if (e.key === 'h' || e.key === 'H') AR_toggleHelp();
  });
  window.addEventListener('keyup', e => {
    if (e.code === 'Space') AR_space = false;
  });

  // ---- per-frame ----
  function tick(dt) {
    dt = clamp(dt, 0, 0.1);
    AR_time += dt;

    // gunship slow circle (r 120, h 95, 60 s), face travel, bank 0.1
    const ga = AR_time * TAU / 60;
    AR_gs.pos.set(Math.cos(ga) * 120, 95, Math.sin(ga) * 120);
    AR_gs.group.position.copy(AR_gs.pos);
    AR_tV.set(-Math.sin(ga), 0, Math.cos(ga)).add(AR_gs.pos);
    AR_gs.group.lookAt(AR_tV);
    AR_gs.group.rotateZ(0.1);
    AR_navMat.opacity = Math.sin(AR_time * TAU * 2) > 0 ? 1 : 0.06;

    // camera: sensor pod under the gunship; look-at drifts toward the slewed aim point.
    // At x1 mostly fixed on the compound; deeper zoom pans the sensor (real FLIR behavior).
    state.camera.position.set(AR_gs.pos.x, AR_gs.pos.y - 2.5, AR_gs.pos.z);
    if (AR_aimValid) AR_camTgt.lerp(AR_aimPoint, 1 - Math.exp(-dt * 2.5));
    const AR_lk = AR_tV2.set(0, 0, 0).lerp(AR_camTgt, AR_PAN[AR_zoom]);
    state.camera.lookAt(AR_lk);
    state.camera.updateMatrixWorld();

    // aim: sensor ray through the reticle NDC, clamped to the 35-degree slew cone
    // around the boresight (gunship -> compound center)
    AR_aimValid = false;
    if (AR_aimActive) {
      AR_gazeDir.set(-AR_gs.pos.x, -AR_gs.pos.y, -AR_gs.pos.z).normalize();
      AR_ray.setFromCamera(AR_ndc, state.camera);
      if (AR_ray.ray.intersectPlane(AR_plane, AR_aimRaw)) {
        const v = AR_tV2.subVectors(AR_aimRaw, AR_gs.pos);
        if (v.length() > 0.5) {
          v.normalize();
          const ca = v.dot(AR_gazeDir);
          if (ca < AR_COS35) {
            // rotate the over-slew vector onto the cone rim
            AR_tV3.copy(v).addScaledVector(AR_gazeDir, -ca);
            if (AR_tV3.lengthSq() > 1e-8) {
              AR_tV3.normalize();
              v.copy(AR_gazeDir).multiplyScalar(AR_COS35).addScaledVector(AR_tV3, AR_SIN35);
            } else {
              v.copy(AR_gazeDir);
            }
          }
          if (v.y < -1e-4) {
            AR_aimPoint.copy(AR_gs.pos).addScaledVector(v, -AR_gs.pos.y / v.y);
          } else {
            AR_aimPoint.copy(AR_gs.pos).addScaledVector(AR_gazeDir, -AR_gs.pos.y / AR_gazeDir.y);
          }
          AR_aimPoint.y = 0;
          AR_aimValid = true;
        }
      }
    }

    // reticle with subtle sensor micro-jitter (visual only; firing uses the exact point)
    AR_jT += dt;
    const jx = 0.1 * Math.sin(AR_jT * 6.1) + 0.07 * Math.sin(AR_jT * 13.7 + 1.3);
    const jz = 0.1 * Math.sin(AR_jT * 5.3 + 0.7) + 0.07 * Math.sin(AR_jT * 11.9 + 2.1);
    AR_ring.visible = AR_aimValid;
    AR_ticks.visible = AR_aimValid;
    if (AR_aimValid) {
      AR_ring.position.set(AR_aimPoint.x + jx, 0.05, AR_aimPoint.z + jz);
      AR_ticks.position.set(AR_ring.position.x, 0.05, AR_ring.position.z);
      const lp = AR_laserGeom.attributes.position;
      lp.setXYZ(0, AR_gs.pos.x, AR_gs.pos.y, AR_gs.pos.z);
      lp.setXYZ(1, AR_aimPoint.x, 0.05, AR_aimPoint.z);
      lp.needsUpdate = true;
      AR_laser.computeLineDistances();
    }

    // hold-to-fire (RMB / Space), rate-limited
    if (AR_rmb || AR_space || AR_lmbHeld) AR_tryHold();
    for (let i = 0; i < AR_WEAPONS.length; i++) if (AR_cd[i] > 0) AR_cd[i] = Math.max(0, AR_cd[i] - dt);

    // reload timers
    for (let i = 0; i < AR_WEAPONS.length; i++) {
      if (!AR_reloading[i]) continue;
      AR_reloadT[i] += dt;
      if (AR_reloadT[i] >= AR_WEAPONS[i].reload) {
        AR_reloading[i] = false;
        AR_ammo[i] = AR_WEAPONS[i].maxAmmo;
        AR_updateAmmo();
      }
    }

    // projectiles (fixed-step integration: deterministic match to the launch solver)
    AR_pAcc += dt;
    let pGuard = 0;
    while (AR_pAcc >= AR_H && pGuard++ < 10) {
      AR_pAcc -= AR_H;
      for (let i = 0; i < AR_pCount; i++) {
        const p = AR_pData[i];
        const w = p.w;
        // NUKE: guided 3-second cinematic flight, guaranteed detonation at designated point.
        if (p.target) {
          p.age += AR_H;
          AR_tV.subVectors(p.target, p.pos);
          const left = AR_tV.length();
          if (left > 0.01) {
            AR_tV.multiplyScalar(Math.min(1, 55 * AR_H / left));
            p.pos.add(AR_tV);
            p.vel.copy(AR_tV).multiplyScalar(1 / AR_H);
          }
          if (left <= 2 || p.age >= 3) {
            p.pos.copy(p.target);
            AR_explode(p.pos, w);
            AR_killProj(i);
            i--;
          } else {
            AR_writeProj(i);
          }
          continue;
        }
        if (w.g) p.vel.y -= w.g * AR_H;
        if (w.drag) {
          const f = 1 - w.drag * AR_H;
          p.vel.x *= f;
          p.vel.y *= f;
          p.vel.z *= f;
        }
        p.pos.x += p.vel.x * AR_H;
        p.pos.y += p.vel.y * AR_H;
        p.pos.z += p.vel.z * AR_H;
        let boom = p.pos.y <= 0;
        if (!boom) {
          const rr = (w.blast + 0.3) * (w.blast + 0.3);
          const blocks = state.blocks;
          for (let j = 0; j < blocks.length; j++) {
            const b = blocks[j];
            if (!b.alive) continue;
            const bdx = b.pos.x - p.pos.x;
            const bdy = b.pos.y - p.pos.y;
            const bdz = b.pos.z - p.pos.z;
            if (bdx * bdx + bdy * bdy + bdz * bdz < rr) { boom = true; break; }
          }
        }
        if (boom) {
          AR_explode(p.pos, w);
          AR_killProj(i);
          i--;
        } else {
          AR_writeProj(i);
        }
      }
      if (AR_pCount > 0) AR_pMesh.instanceMatrix.needsUpdate = true;
    }

    // fps + 10 Hz text updates
    AR_fpsFrames++;
    AR_fpsAcc += dt;
    if (AR_fpsAcc >= 0.1) {
      AR_fps = Math.round(AR_fpsFrames / AR_fpsAcc);
      AR_fpsFrames = 0;
      AR_fpsAcc = 0;
    }
    AR_hudAcc += dt;
    if (AR_hudAcc >= 0.1) {
      AR_hudAcc = 0;
      AR_updateAmmo();
      AR_updateAim();
      AR_updateFps();
    }
  }

  AR_chips[0].classList.add('sel');
  refreshHud();
  console.log('[ARSENAL] C-130 online: sensor-locked camera, 3 weapons, WHOT default');

  return {
    selectWeapon,
    fireAt,
    tick,
    reset,
    refreshHud,
    markStructure,
    setThermal,
    zoom,
    slew,
    aimPoint: AR_aimPoint,
  };
}

// ===== SECTION D: MAIN =====
const app = document.getElementById('app');
const scene = new THREE.Scene();
const camera = new THREE.PerspectiveCamera(30, window.innerWidth / window.innerHeight, 0.5, 900);
camera.position.set(0, 95, 0);

const dir = new THREE.DirectionalLight(0xfff2dd, 3.0); // soft warm daylight, high
dir.position.set(60, 90, -40);
dir.target.position.set(4, 0, 6);
dir.castShadow = true;
dir.shadow.mapSize.set(2048, 2048);
dir.shadow.camera.left = -60;
dir.shadow.camera.right = 60;
dir.shadow.camera.top = 60;
dir.shadow.camera.bottom = -60;
dir.shadow.camera.near = 5;
dir.shadow.camera.far = 260;
dir.shadow.bias = -0.0004;
scene.add(dir, dir.target);
const hemi = new THREE.HemisphereLight(0xbfe3ff, 0x7a9a5a, 2.2);
const fill = new THREE.DirectionalLight(0xcfe4ff, 1.1); // bright sky fill from the opposite side
fill.position.set(-60, 40, 50);
scene.add(fill);
scene.add(hemi);

const state = {
  scene: scene,
  camera: camera,
  blocks: [],
  structures: [],
  mats: {},
  water: null,
  lights: { dir: dir, hemi: hemi },
  thermal: true,
  score: 0,
  downgraded: false,
  gunship: null,
  destruction: null,
  arsenal: null,
  applyThermal: null,
  onBlockDestroyed: null,
  onStructureDestroyed: null,
  onResetRequest: null,
};

let renderer;
try {
  renderer = new THREE.WebGLRenderer({antialias:true});
} catch (err) {
  console.warn('[MAIN] WebGL unavailable:', err);
  throw err;
}
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 1.5));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
scene.fog = new THREE.Fog(0xdfeeff, 180, 700); // airy depth haze
renderer.toneMappingExposure = 1.45;
app.appendChild(renderer.domElement);

buildGarden();
state.applyThermal = applyThermal;
state.destruction = new Destruction();
state.arsenal = initArsenal();
state.arsenal.setThermal(true); // WHOT is the default view (body class + scene swap)
state.onBlockDestroyed = () => {};
state.onStructureDestroyed = (s) => { if (state.arsenal) state.arsenal.markStructure(s); };
state.onResetRequest = () => resetAll();

function resetAll() {
  resetGarden();
  if (state.destruction) state.destruction.reset();
  if (state.arsenal) state.arsenal.reset();
  state.score = 0;
  if (state.thermal) applyThermal(true);
}

let lastT = -1;
let fpsE = 60;
let lowT = 0;
function frame(tms) {
  const dt = lastT < 0 ? 0.016 : clamp((tms - lastT) / 1000, 0, 0.05);
  lastT = tms;
  if (dt > 0) fpsE += (1 / dt - fpsE) * 0.05;
  gardenTick(dt);
  if (state.arsenal) state.arsenal.tick(dt);
  if (state.destruction) state.destruction.update(dt);
  if (!state.downgraded) {
    if (fpsE < 42) {
      lowT += dt;
      if (lowT > 3) downgrade();
    } else {
      lowT = 0;
    }
  }
  renderer.render(scene, camera);
}

function downgrade() {
  state.downgraded = true;
  renderer.setPixelRatio(1);
  if (state.water) {
    state.water.meshA.material = state.water.cheap;
    state.water.meshB.material = state.water.cheap;
  }
  dir.shadow.mapSize.set(1024, 1024);
  if (dir.shadow.map) { dir.shadow.map.dispose(); dir.shadow.map = null; }
  console.log('[MAIN] performance downgrade: DPR 1, cheap water, shadow map 1024');
}

window.addEventListener('resize', () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
});
// headless-verification hook: exposes internals to the node harness/probe
state.THREE = THREE;
window.__ac130 = { state: state, THREE: THREE, renderer: renderer };
renderer.setAnimationLoop(frame);
